// vivekananda_te.dart
// Swami Vivekananda quotes and articles (Telugu)

import '../articlesquotes.dart';

final vivekanandaSaintTe = Saint(
  'vivekananda',
  'Swami Vivekananda',
  'assets/images/vivekananda.jpg',
  [
    'ఎదురు నిలబడి, మేల్కొని, లక్ష్యాన్ని చేరేవరకు ఆగకండి.',
    'ఒక ఆలోచనను స్వీకరించండి. ఆ ఆలోచననే మీ జీవితం చేయండి — దానిని ఆలోచించండి, దానిని కలగంటండి, ఆ ఆలోచనలోనే జీవించండి.',
    'వీరుడిగా ఉండు. ఎల్లప్పుడూ చెప్పు, \'నాకు భయం లేదు.\' భయం మరణం, భయం పాపం, భయం నరకం.',
    'ఈ ప్రపంచం ఒక మహా నైతిక వ్యాయామశాల, అందులో మనం అందరం ఆధ్యాత్మికంగా మరింత బలవంతులు కావడానికి వ్యాయామం చేయాలి.',
    'మీరు గీతా అధ్యయనంతో పోలిస్తే ఫుట్‌బాల్ ద్వారా స్వర్గానికి మరింత దగ్గరగా ఉంటారు.',
    'సత్యం కోసం అన్నీ త్యాగం చేయవచ్చు, కానీ ఏదీ సత్యం కోసం త్యాగం చేయబడలేను.',
    'జీవుని సేవించేవాడు, నిజానికి శివుని ఆరాధిస్తున్నాడు.',
    'ఓ భారతమాత! నీకు మరువరాదు, నీ శరీరమూ రక్తమూ అయిన నీ తమ్ముళ్లను, ఆ దిగువ తరగతులను, అజ్ఞానులను, పేదలను, నిరక్షరాస్యులను, చెప్పులు కుట్టేవారిని, వీధులు ఊడ్చేవారిని.',
    'మన ఆలోచనలు మనల్ని ఎలా మలచుకున్నాయో, మనం అలా ఉంటాము; కాబట్టి మీరు ఏమి ఆలోచిస్తున్నారో జాగ్రత్తగా ఉండండి. మాటలు రెండవ స్థానంలో ఉంటాయి. ఆలోచనలు జీవిస్తాయి; అవి దూరం ప్రయాణిస్తాయి.',
    'అమెరికా సోదరులు మరియు సోదరీమణులారా, మీరు అందించిన ఆత్మీయ స్వాగతానికి ప్రతిస్పందిస్తూ నిలబడటం నా హృదయాన్ని వర్ణించలేని ఆనందంతో నింపుతుంది.',
    'సర్వశక్తి నీలోనే ఉంది; నువ్వు ఏదైనా, అన్నీ చేయగలవు.',
    'తనను బలహీనుడిగా భావించడం అత్యంత పాపం.',
    'శక్తి జీవితం, బలహీనత మరణం. విస్తరణ జీవితం, సంకోచం మరణం. ప్రేమ జీవితం, ద్వేషం మరణం.',
    'ప్రపంచం మనం బలవంతులుగా మారడానికి వచ్చిన గొప్ప వ్యాయామశాల.',
    'మీరు ఏదైతే ఆలోచిస్తారో, మీరు అదే అవుతారు. మీరు మీను బలహీనంగా భావిస్తే, మీరు బలహీనులవుతారు; మీరు మీను బలవంతులుగా భావిస్తే, మీరు బలవంతులవుతారు.',
    'ఎదురు నిలబడి, ధైర్యంగా, బలంగా ఉండండి. మీ భవిష్యత్తు మీ చేతుల్లోనే ఉందని తెలుసుకొని, ఆ బాధ్యతను మీ భుజాలపై తీసుకోండి.',
    'మీరు అందరూ గొప్ప కార్యాలు చేయడానికి పుట్టినవారే అని నమ్మకం ఉంచండి, నా ధైర్యవంతులారా!',
    'మీరు మీపై నమ్మకం ఉంచినప్పుడే దేవునిపై నమ్మకం ఉంచగలరు.',
    'వీరుడిగా ఉండు. ఎప్పుడూ చెప్పు, "నాకు భయం లేదు."',
    'ఆత్మకు అసాధ్యం అనేది ఏదీ లేదని ఎప్పుడూ అనుకోకండి.',
    'ఏదీ అడ్డంకిగా భావించవద్దు. ఈ శరీరం సుఖదుఃఖాలతో ఎంతకాలం నిలుస్తుంది? మానవ జన్మ పొందినప్పుడు, ఆత్మను మేల్కొల్పి చెప్పండి — నేను భయరహిత స్థితిని పొందాను!',
    'మనకు అనంతమైన సహనం, అనంతమైన పవిత్రత, అనంతమైన పట్టుదల అవసరం. విజయం తప్పక వస్తుంది.',
    'అనంతమైన సహనాన్ని కలిగి ఉండు, విజయము నీదే.',
    'పోరాడే వ్యక్తి, ప్రయత్నించని వ్యక్తికంటే మెరుగైనవాడు.',
    'స్వతంత్రంగా ఉండండి; ఎవరి నుండి ఏమీ ఆశించవద్దు. మీ జీవితాలను వెనక్కి చూసినప్పుడు, మీరు ఎప్పుడూ ఇతరుల నుండి సహాయం పొందడానికి వ్యర్థంగా ప్రయత్నిస్తూ ఉండేవారని మీరు గమనిస్తారు, కానీ అది ఎన్నడూ రాలేదు.',
    'భయరహితత్వం అనే ధర్మమే బోధించబడవలసిన ఏకైక ధర్మం.',
    'ఎవరిని లేదా ఏదైనా కోసం వేచి ఉండకండి. మీకు సాధ్యమైనంత చేయండి. మీ ఆశలను ఎవరిపైనా పెట్టకండి.',
    'మీకు కావలసిన సమస్త బలం మరియు సహాయం మీలోనే ఉంది.',
    'మీ జీవితంలో ప్రమాదాలను స్వీకరించండి. మీరు గెలిస్తే, మీరు నాయకత్వం వహించవచ్చు; మీరు ఓడిపోతే, మీరు మార్గనిర్దేశం చేయవచ్చు.',
    'మనం కోరుకునే విద్య మనసుకు బలాన్ని, బుద్ధికి విస్తారాన్ని, వ్యక్తిత్వానికి రూపాన్ని అందించాలి, దాని ద్వారా మనం స్వయంగా నిలబడగలగాలి.',
    'విద్య అనేది మీ మెదడులో నింపబడిన సమాచారం పరిమాణం కాదు, అది జీర్ణించని విధంగా మీ జీవితమంతా అల్లకల్లోలంగా నడుస్తుంది.',
    'ఇచ్ఛాశక్తి ప్రవాహం మరియు వ్యక్తీకరణ నియంత్రణలోకి వచ్చి ఫలప్రదంగా మారే శిక్షణను విద్య అంటారు.',
    'నా దృష్టిలో విద్య యొక్క అసలు సారాంశం మనస్సు ఏకాగ్రత, కాకపోతే వాస్తవాల సేకరణ కాదు.',
    'ముందుగా స్వభావాన్ని నిర్మించండి—అది మీరు చేయగలిగే అత్యున్నత కర్తవ్యం.',
    'ధనం ఫలితాన్ని ఇవ్వదు, పేరు కూడా కాదు; ఖ్యాతి ఫలితాన్ని ఇవ్వదు, విద్య కూడా కాదు. ప్రేమే ఫలితాన్ని ఇస్తుంది; గుణమే కఠినమైన కష్టాల గోడలను ఛేదిస్తుంది.',
    'పాత్రను వేల సార్లు తడబడుతూ స్థాపించాలి.',
    'ప్రతి మూర్ఖుడూ ఏదో ఒక సమయంలో వీరుడిగా మారవచ్చు. ఒక మనిషి సాధారణంగా చేసే పనులను గమనించండి; అవే నిజంగా గొప్ప మనిషి యొక్క నిజమైన స్వభావాన్ని తెలియజేస్తాయి.',
    'పాత్ర అనేది పునరావృతమైన అలవాట్ల సమాహారం, మరియు పునరావృతమైన అలవాట్ల ద్వారానే పాత్రలో మార్పు సాధ్యమవుతుంది.',
    'మనము చేసే ప్రతి పని, శరీరానికి సంబంధించిన ప్రతి కదలిక, మనం ఆలోచించే ప్రతి ఆలోచన మన మనస్సులో ఒక ముద్రను వదిలిపెడుతుంది. మన స్వభావం ఈ ముద్రల సమాహారమే.',
    'ఒక ఆలోచనను తీసుకోండి. ఆ ఆలోచననే మీ జీవితంగా మార్చుకోండి - దానిని ఆలోచించండి, దాని గురించి కలలు కనండి, ఆ ఆలోచనతో జీవించండి. మీ మెదడు, కండరాలు, నరాలు, శరీరంలోని ప్రతి భాగం ఆ ఆలోచనతో నిండిపోవాలి, ఇతర ఆలోచనలను పూర్తిగా వదిలేయండి. ఇదే విజయానికి మార్గం.',
    'నిజమైన విజయానికి, నిజమైన ఆనందానికి గొప్ప రహస్యం ఇదే: ఎలాంటి ప్రతిఫలం ఆశించకుండా, సంపూర్ణంగా నిస్వార్థంగా ఉండే మనిషి అత్యంత విజయవంతుడు.',
    'కార్యాన్ని కర్తవ్యంగా చేయండి. పూజను పూజార్థం చేయండి. సత్కార్యాలు చేయడం మంచిదేనని వాటిని చేయండి. అంతే, మరెంతో ఆశించకండి.',
    'ధర్మరంగంలో సత్యాన్ని ప్రచారం చేస్తూ మరణించడం, లోకిక పురుగుల్లా మరణించడంకన్నా ఎంతో శ్రేయస్కరం.',
    'అస్తిత్వం యొక్క మొత్తం రహస్యం భయాన్ని విడిచిపెట్టడంలోనే ఉంది.',
    'ఒక రోజు మీరు ఏ సమస్యలను ఎదుర్కోలేకపోతే - మీరు తప్పు మార్గంలో ప్రయాణిస్తున్నారని నిశ్చయంగా తెలుసుకోవచ్చు.',
    'అనంతమైన సహనం మరియు అనంతమైన శక్తి తన వెనుక ఉన్నవాడు మాత్రమే విజయం సాధిస్తాడు.',
    'ముందుకు సాగండి, నా ధైర్యవంతులారా. మనం ఇప్పుడే ప్రారంభించాం. నిరాశ చెందకండి! చాలు అనడం ఎప్పుడూ వద్దు!',
    'హృదయం మరియు మేధస్సు మధ్య సంఘర్షణ వచ్చినప్పుడు, మీ హృదయాన్నే అనుసరించండి.',
    'శుద్ధమైనవాడు, స్వార్థరహితుడైనవాడు మాత్రమే దేవుని చూడగలడు. దేవుని చూడటం అంటే దేవుడిగా మారడం.',
    'ఈ జీవితం చాలా చిన్నది, ప్రపంచపు ఆర్భాటాలు తాత్కాలికం, కానీ ఇతరుల కోసం జీవించే వారే నిజంగా జీవిస్తారు, మిగతావారు జీవించి ఉన్నంత మాత్రాన మరణించిన వారితో సమానం.',
    'మహానుభావమైన కార్యాలు మహత్తరమైన అడ్డంకులను అధిగమించి సాధించబడతాయి.',
    'పరిపూర్ణంగా నిస్వార్థంగా ఉండి, స్థిరంగా ఉండి, ముందుకు సాగండి. మనం గొప్ప పనులు చేస్తాము; భయపడవద్దు.',
    'మనము ఇతరులకు మేలు చేయడానికి ఎంత ఎక్కువగా బయటకు వస్తామో, అంత ఎక్కువగా మన హృదయాలు పవిత్రమవుతాయి.',
    'ఆధ్యాత్మిక జీవితానికి అత్యంత సహాయపడేది ధ్యానం. ఆ తరువాత మంచివారి సాంగత్యం.',
    'మనకు వేడి అందించే అగ్ని, మనల్ని దహించగలదు కూడా; అది అగ్ని యొక్క తప్పు కాదు.',
    'ఒక వ్యక్తి స్వభావాన్ని అర్థం చేసుకోవడానికి ఉత్తమ పరీక్ష, వారు తమకు ఏమీ చేయలేని వారిని ఎలా ప్రవర్తిస్తారో చూడటమే.',
    'ఇతరుల నుండి మేలైనదాన్ని నేర్చుకో, కానీ దానిని నీలోనికి తీసుకురా మరియు నీ స్వంత శైలిలో దానిని ఆత్మసాత్కరించుకో; ఇతరులుగా మారిపోవద్దు.',
    'మనకు సమీపంలో ఉన్న కర్తవ్యాన్ని నిర్వర్తించడం ద్వారా మాత్రమే పైకి ఎదగగలము, అలా శక్తిని సేకరించి, అత్యున్నత స్థితిని చేరుకునే వరకు ముందుకు సాగాలి.',
    'ఆనందంగా ఉండండి. మీ స్వంత ఆదర్శాన్ని పట్టుకోండి. అందరి సేవకుడిగా ఉండండి.',
    'మతం అంటే మనిషిలో ఇప్పటికే ఉన్న దైవత్వం వెలుగులోకి రావడం.',
    'మీరు లోపల నుండి వెలుపలికి ఎదగాలి. ఎవరూ మీకు నేర్పలేరు, ఎవరూ మీను ఆధ్యాత్మికుడిగా చేయలేరు. మీ ఆత్మ తప్ప మరెవరూ గురువు కాదు.',
    'ప్రతి మనిషి శరీరంలో దేవుడు ఆలయంలో కూర్చున్నట్లు నేను గ్రహించిన క్షణం, ప్రతి మనిషి ముందు గౌరవంతో నిలబడి, అందులో దేవుణ్ణి చూసిన క్షణం - ఆ క్షణం నేను బంధనాల నుండి విముక్తుడనవుతాను.',
    'మీ జీవితాన్ని సమస్త జనుల శ్రేయస్సు మరియు ఆనందానికి అంకితం చేయడం ధర్మం. మీ స్వంత ప్రయోజనం కోసం మీరు చేసే ఏదైనా ధర్మం కాదు.',
    'మీ స్వభావానికి నిబద్ధంగా ఉండటం గొప్ప మతం. మీపై నమ్మకం ఉంచుకోండి!',
    'భారంగా మోయకండి; అసక్తి లేకుండా ఉండండి.',
    'మత విశ్వాసాల వైవిధ్యం ఒక ప్రయోజనం, ఎందుకంటే అన్ని విశ్వాసాలు మనలను ధార్మిక జీవితాన్ని గడపడానికి ప్రేరేపించేంతవరకు మంచివే.',
    'మతానికి సామాజిక చట్టాలను రూపకల్పన చేయడం మరియు జీవుల మధ్య తేడాలను పట్టించుకోవడం అవసరం లేదు, ఎందుకంటే దాని లక్ష్యం మరియు అంతిమం అన్ని అబద్ధాలు మరియు భయంకరమైన విషయాలను తొలగించడం.',
    'మీరు ఆధ్యాత్మికంగా మారుతున్న తొలి సంకేతం మీరు ఆనందంగా మారడం.',
    'అంధంగా నమ్మడం మనుష్య ఆత్మను క్షీణింపజేస్తుంది. నాస్తికుడిగా ఉండండి, కానీ ఏదైనా ప్రశ్నించకుండా నమ్మకండి.',
    'మనం మతాన్ని గౌరవంతో మరియు ప్రేమతో సమీపించాలి, అప్పుడు మన హృదయం నిలబడి చెబుతుంది, "ఇది సత్యం, ఇది అసత్యం."',
    'మీ స్వభావానికి నమ్మకంగా ఉండటం గొప్ప మతం. మీ మీద నమ్మకం ఉంచుకోండి!',
    'ఏమీ లేని దరిద్రుడు మహాదేవుడు. అన్నీ ఉన్న ధనవంతుడు అందరి సేవకుడు.',
    'నేను జీవించేంతవరకు, నా ఆత్మపై నాకు నియంత్రణ ఉంటుంది.',
    'పూర్తిగా సమర్పణతో, పూర్తిగా నిర్లిప్తతతో ఉండండి; అప్పుడు మాత్రమే మీరు నిజమైన పనిని చేయగలరు.',
    'ఏదీ ఆశించకండి, ఏదీ దూరం చేయకండి, వచ్చినదాన్ని స్వీకరించండి.',
    'ఏమి అనుభవించక, ఏమి తెలియక, ఏమి చేయక, ఏమి కలిగి ఉండక, అన్నింటినీ దేవునికి అర్పించి, "నీ చిత్తమే జరగనియ్యుము" అని పూర్తిగా చెప్పుము.',
    'మనం కేవలం ప్రకాశవంతంగా, ఆనందంగా ఉండటమే కాకుండా, ఇతరులను కూడా ప్రకాశవంతంగా, ఆనందంగా చేయాలి.',
    'మానవ జీవిత లక్ష్యం స్వాతంత్ర్యం పొందడం.',
    'ప్రతి ఆత్మలో దైవత్వం స్ఫురించగల శక్తి ఉంది.',
    'రోజుకు ఒక్కసారైనా మీతో మీరు మాట్లాడండి, లేనిపక్షంలో ఈ లోకంలో ఒక తెలివైన వ్యక్తిని కలిసే అవకాశం కోల్పోతారు.',
    'సత్యం వెయ్యి విధాలుగా చెప్పబడవచ్చు, అయినప్పటికీ ప్రతి ఒక్కటి సత్యమే.',
    'మన ఆలోచనలు మనల్ని రూపొందిస్తాయి. మన ఆలోచనలు చెడ్డవైతే, మనం చెడ్డవారమవుతాము. మన ఆలోచనలు మంచివైతే, మనం మంచివారమవుతాము.',
    'మనస్సు ఒక పిచ్చి కోతి వంటిది, దానిని కట్టిపడేయడానికి సంకల్పమే తాడు.',
    'ఆధ్యాత్మిక జీవనానికి అత్యంత సహాయపడేది ధ్యానం. ఆ తరువాత మంచివారి సాంగత్యం.',
    'మనస్సు ఒక శక్తి, దానిని ఉపయోగించి ప్రపంచాన్ని జయించవచ్చు.',
    'ఏదికైనా భయపడవద్దు. నువ్వు అద్భుతమైన పనిని చేస్తావు. భయపడిన క్షణంలో, నువ్వు ఎవరు కాదు.',
    'మనము విశ్వంతో ఏకత్వంలో ఉన్నంత మాత్రమూ, మనతోనూ సారూప్యంగా ఉంటాము.',
    'విజయాన్ని సాధించేందుకు పుట్టిన మనసు, దృఢ సంకల్పంతో కలసి, పట్టుదలతో ముందుకు సాగుతుంది.',
    'ప్రతి మనిషి స్వభావం మనస్సులోని ఈ ముద్రల సమాహారంతో నిర్ణయించబడుతుంది.',
    'శ్రేష్ఠమైన బోధనకు జీవంత ఉదాహరణగా ఉండే పవిత్రుడు నిజమైన గురువు.',
    'మన ఆలోచనలు మనల్ని ఎలా మలిచాయో మనం అలా ఉంటాము; కాబట్టి మీరు ఏమి ఆలోచిస్తున్నారో జాగ్రత్తగా ఉండండి.',
    'సర్వ జ్ఞానం మనలోనే ఉంది. మనసు ఆ జ్ఞానాన్ని వెలికితీయగలదు.',
    'మనస్సు ఒక జల్లెడలా పనిచేస్తుంది, దాని ద్వారా విశ్వ జ్ఞానం మన చైతన్యంలో ప్రవహిస్తుంది.',
    'మనసు మహా జ్ఞాన సాంద్రం. ఆ జ్ఞానం వెలుపలికి ప్రవహించే మార్గం మన ఆలోచనలు మాత్రమే.',
    'మనస్సు ఒక కట్టుకోని గుఱ్ఱంలా ఉంటుంది, దానిని శాంతపరచాలి. ఇంద్రియాలు అడ్డాలు, సంకల్పమే స్వారీదారు.',
    'మీ మనస్సును నియంత్రించాలి. మనస్సే మీ ఆనందం మరియు దుఃఖానికి మూలం.',
    'భావనలు బలంగా ఉన్నప్పుడు వాస్తవాన్ని సృష్టిస్తాయి. బలమైన మనస్సు పర్వతాలను కదిలించగలదు.',
    'మీ ఆలోచనలు మీను రూపుదిద్దుతాయి. మీరు అనుభవించే భావాలు మీ వైపుకు ఆకర్షిస్తాయి. మీరు ఊహించే దృశ్యాలు మీరు సృష్టిస్తారు.',
    'మనస్సు మంచికి లేదా చెడుకు శక్తివంతమైన సాధనంగా మారవచ్చు. దానిని ఎలా ఉపయోగించాలో నిర్ణయించడం మీ చేతిలో ఉంది.',
    'ఇతరుల కోసం జీవించే వారే నిజంగా జీవిస్తారు.',
    'ఈ ప్రపంచంలోని అన్ని భేదాలు పరిమాణంలోనే ఉంటాయి, స్వరూపంలో కాదు, ఎందుకంటే ఏకత్వమే అన్నింటి రహస్యం.',
    'ఇతరుల నుండి మంచి విషయాలను నేర్చుకోండి, కానీ వాటిని ఆత్మసాత చేసుకుని, మీ స్వంత మార్గంలో అవగాహన చేసుకోండి.',
    'మనము విశ్వంతో ఏకత్వంలో ఉన్నప్పుడు, మనతోనూ అంతే సమన్వయం కలిగి ఉంటాము.',
    'మనము ధైర్యంగా, సాహసంతో వారి లోపాలను చెప్పగలగాలి, కానీ అదే సమయంలో వారికి చెందాల్సిన కీర్తిని కూడా ఇవ్వగలగాలి.',
    'ఎవరినీ హానిచేయవద్దు. అసూయ పడవద్దు. ద్వేషించవద్దు. ప్రేమే ఏకైక ధర్మం.',
    'ఇతరులతో వాదించవద్దు. సహనంతో ఉండండి. అన్ని మతాలను సత్యంగా స్వీకరించండి.',
    'మహానుభావులు ఆలోచిస్తారు, మనం కూడా ఆలోచిస్తాం. కానీ ఒక తేడా ఉంది. మనం ఆలోచిస్తాం కానీ మన శరీరాలు ఆ ఆలోచనలను అనుసరించవు.',
    'నా ఆదర్శం కొద్ది మాటల్లో చెప్పగలిగేది, అది: మానవజాతికి వారి దైవత్వాన్ని బోధించడం, మరియు జీవితంలోని ప్రతి కదలికలో దాన్ని ఎలా వ్యక్తీకరించాలో తెలియజేయడం.',
    'జీవిత లక్ష్యం, బాహ్య మరియు అంతర్గత ప్రకృతిని నియంత్రించి, మనలోని దైవత్వాన్ని వ్యక్తీకరించడం.',
    'ప్రతి ఆత్మలో దైవత్వం సంతృప్తంగా ఉంటుంది. ఈ దైవత్వాన్ని ఆంతర్యంలో ప్రదర్శించడం లక్ష్యం. దీనిని సాధించడానికి ప్రకృతిని, ఆంతర్యాన్ని నియంత్రించాలి. ఇది కర్మ ద్వారా, భక్తి ద్వారా, మనోనిగ్రహం ద్వారా, లేదా తత్వశాస్త్రం ద్వారా చేయవచ్చు — ఒక్కటిగా, లేదా ఎక్కువగా, లేదా అన్ని ద్వారా — మరియు విముక్తి పొందాలి.',
    'లేచి, మేల్కొని, లక్ష్యాన్ని చేరేవరకు ఆగకండి. బలహీనత మరణం; బలం జీవితం. విస్తరణ జీవితం; సంకోచం మరణం.',
    'మీరు లోపల నుండి బయటకు పెరగాలి. ఎవ్వరూ మీకు బోధించలేరు, ఎవ్వరూ మిమ్మల్ని ఆధ్యాత్మికంగా చేయలేరు. మీ ఆత్మ తప్ప మరెవ్వరూ గురువు కాదు.',
    'మీ స్వభావానికి నమ్మకంగా ఉండటం గొప్ప మతం. మీపై విశ్వాసం కలిగి ఉండండి.',
    'అన్ని శక్తులు మీలోనే ఉన్నాయి; మీరు ఏదైనా, అన్నీ చేయగలరు. ఆ విశ్వాసం కలిగి ఉండండి, మీరు బలహీనులని నమ్మవద్దు.',
    'అస్తిత్వం యొక్క గూఢ రహస్యం భయాన్ని విడిచిపెట్టడంలో ఉంది. ఏమి జరుగుతుందోనని ఎప్పుడూ భయపడకండి, ఎవరి మీదా ఆధారపడకండి.',
    'శుద్ధత, సహనం, మరియు పట్టుదల విజయానికి మూడు ముఖ్యమైన అంశాలు, మరియు అన్నింటికంటే ప్రేమ ప్రధానమైనది.',
    'ఎదురు నిలబడి, ధైర్యంగా, బలంగా ఉండండి. మొత్తం బాధ్యతను మీ భుజాలపై తీసుకోండి, మీరు మీ స్వంత విధిని సృష్టించేవారిగా తెలుసుకోండి.',
    'హృదయం మరియు మేధస్సు మధ్య సంఘర్షణలో, హృదయాన్నే అనుసరించు.',
    'రోజుకు కనీసం ఒక్కసారైనా మీతో మీరే మాట్లాడండి; లేనిపక్షంలో ఈ లోకంలో అద్భుతమైన వ్యక్తిని కలవడం మిస్సవుతుందేమో.',
    'మనలను వేడి చేసే అగ్ని మనలను దహించగలదు కూడా; ఇది అగ్ని యొక్క తప్పు కాదు.',
    'ప్రతి మనిషి శరీరమనే దేవాలయంలో దేవుని సాక్షాత్కారం పొందిన క్షణం, ప్రతి మనిషి ముందు భక్తితో నిలబడి, అతనిలో దేవుని దర్శించిన క్షణం — ఆ క్షణమే నేను బంధనాల నుండి విముక్తుడనౌతాను.',
    'మానవునిలో ఇప్పటికే ఉన్న దైవత్వం వ్యక్తీకరణే ధర్మం.',
    'ఈ లోకంలో ఉన్న భేదాలు పరిమాణంలోనే ఉంటాయి, స్వరూపంలో కాదు, ఎందుకంటే ఏకత్వమే అన్నిటి రహస్యం.',
    'సౌకర్యం సత్యానికి పరీక్ష కాదు. సత్యం తరచుగా \'సౌకర్యం\' నుండి దూరంగా ఉంటుంది.',
    'ప్రపంచం మనం బలంగా మారడానికి వచ్చిన గొప్ప వ్యాయామశాల.',
    'యావత్తు లక్షలాది మంది ఆకలితో మరియు అజ్ఞానంతో జీవిస్తుంటే, వారి ఖర్చుతో విద్య పొందిన ప్రతి వ్యక్తి వారికి కించిత్తు శ్రద్ధ చూపకపోతే, అతన్ని నేను ద్రోహిగా భావిస్తాను.',
    'తమను బలహీనులమని భావించటం అత్యంత పాపం.',
    'మన ఆలోచనలు మనల్ని ఎలా తీర్చిదిద్దాయో మనమే అవుతాము; కాబట్టి మీరు ఏమి ఆలోచిస్తున్నారో జాగ్రత్తగా ఉండండి.',
    'ఏదీ భౌతికం అతన్ని కలవరపెట్టలేనప్పుడు ఆ మనిషి అమృతత్వాన్ని పొందాడు.',
    'మీపై నమ్మకం లేకుండా, దేవునిపై నమ్మకం ఉంచలేరు.',
    'మీరు మీ త్రిశతముపై ముప్పది కోట్ల పురాణ దేవతలపై విశ్వాసం ఉంచినా, మీపై విశ్వాసం లేకపోతే, మీకు విముక్తి లేదు.',
    'ఇతరుల నుండి మంచి విషయాలను నేర్చుకో, కానీ వాటిని స్వీకరించి, నేర్చుకుంటూ ఇతరులుగా మారిపోకు.',
    'మీ జీవితంలో సాహసాలు చేయండి. మీరు గెలిస్తే, మీరు నడిపించగలరు; మీరు ఓడితే, మీరు మార్గనిర్దేశం చేయగలరు.',
    'ఒకేసారి ఒక పని చేయండి, దానిని చేస్తూ మీ ఆత్మను పూర్తిగా అందులోనే లీనమై, ఇతర విషయాలను విస్మరించండి.',
    'బాహ్య ప్రకృతి అనేది అంతర్గత ప్రకృతిని విస్తరించి చూపిన రూపమే.',
    'వీరుడిగా ఉండండి. ఎల్లప్పుడూ \'నాకు భయం లేదు\' అని చెప్పండి. అందరికీ చెప్పండి — \'భయపడకండి.\'',
    'మనము ఇతరులకు మేలు చేయడానికి ఎంత ఎక్కువగా ముందుకు వస్తామో, అంత ఎక్కువగా మన హృదయాలు పవిత్రమవుతాయి, మరియు ఆ హృదయాలలో దేవుడు నివసిస్తాడు.',
    'బలమే ధర్మం; బలహీనత పాపం.',
    'ఏమీ అనుభవించకండి, ఏమీ తెలియకండి, ఏమీ చేయకండి, ఏమీ కలిగి ఉండకండి, అన్నీ దేవునికి అర్పించండి, మరియు పూర్తిగా, \'నీ చిత్తం జరగనీ\' అని చెప్పండి.',
    'మనలో ఆవేశం తక్కువగా ఉంటే, మన పని మెరుగ్గా జరుగుతుంది. మనం ఎంత శాంతంగా ఉంటామో, మన పని అంత సాఫల్యంగా పూర్తవుతుంది.',
    'అనుభవమే మనకు ఉన్న ఏకైక గురువు. మనం జీవితాంతం మాట్లాడి, తర్కించినా, సత్యం యొక్క ఒక్క మాటను కూడా అర్థం చేసుకోలేము.',
    'ప్రేమ అనేది విస్తరణ; స్వార్థం అనేది సంకోచం.',
    'మెదడు మరియు కండరాలు సమకాలీనంగా అభివృద్ధి చెందాలి.',
    'మీ లక్ష్యాలను మీ సామర్థ్యాల స్థాయికి తగ్గించకండి. బదులుగా, మీ సామర్థ్యాలను మీ లక్ష్యాల ఎత్తుకు పెంచండి.',
    'మీరు ఏది నమ్ముతారో, మీరు అదే అవుతారు. మీరు మీరే బలహీనమని నమ్మితే, మీరు బలహీనులవుతారు; మీరు మీరే బలవంతులమని నమ్మితే, మీరు బలవంతులవుతారు.',
    'శారీరకంగా, మానసికంగా, ఆధ్యాత్మికంగా బలహీనత కలిగించే ఏదైనా విషంగా భావించి దూరం చేయాలి.',
    'ముందుగా మీ శరీరాన్ని బలపరచండి. అప్పుడే మీరు మనస్సుపై నియంత్రణ పొందగలుగుతారు.',
    'ఏదినీ భయపడవద్దు. నువ్వు అద్భుతమైన కార్యాలు చేస్తావు. భయరహితతే క్షణంలోనే స్వర్గాన్ని తెస్తుంది.',
    'ధ్యానశక్తి మాత్రమే జ్ఞాననిధి తాళం తెరవగలిగే కీ.',
    'దరిద్రులను, బలహీనులను, రోగులను, అజ్ఞానులను సేవించండి మరియు వారిని దేవుడిగా భావించండి.',
    'ఆధ్యాత్మిక జీవితానికి అత్యంత సహాయపడేది ధ్యానం. ధ్యానంలో మనం భౌతిక పరిస్థితులన్నింటినీ విడిచిపెడతాము.',
    'ప్రపంచం పొందిన సమస్త జ్ఞానం మనసు నుంచే ఉద్భవిస్తుంది; విశ్వం యొక్క అనంత గ్రంథాలయం మీ మనసులోనే ఉంది.',
    'భూమిని వీరులు అనుభవిస్తారు — ఇది అచంచలమైన సత్యం.',
    'కార్యఫలాలను విడిచిపెట్టు — కేవలం ధర్మార్థం సత్కార్యాలు చేయి.',
    'ప్రతి కార్యం ఈ దశలను దాటాలి — హాస్యం, వ్యతిరేకత, ఆపై ఆమోదం.',
    'అన్ని విద్యలు, అన్ని శిక్షణల లక్ష్యం మనిషిని నిర్మించడమే కావాలి.',
    'నిస్వార్థత ఎక్కువ ఫలితాన్ని ఇస్తుంది, కానీ దానిని ఆచరించడానికి మనుషులకు సహనం ఉండదు.',
    'పోరాడే వ్యక్తి ప్రయత్నించని వ్యక్తికంటే మెరుగైనవాడు.',
    'అన్ని విస్తరణలు జీవితం; అన్ని సంకోచాలు మరణం.',
    'ఏదీ కోరకు, ఏదీ దూరం చేయకు; వచ్చినదాన్ని స్వీకరించు.',
    'నిజం ఏ సమాజానికీ, ప్రాచీనమో ఆధునికమో, వందనం చేయదు.',
    'తమను తాము బంగారంగా మార్చుకోవాలంటే, ఒకరు తపస్సులో తపించాలి.',
    'ఆలోచన మరియు వ్యక్తీకరణ స్వేచ్ఛ ప్రగతికి మొదటి ప్రమాణం.',
    'మనం కోరుకునేది అలాంటి విద్య, దానివల్ల మనసు బలపడుతుంది, బుద్ధి విస్తరిస్తుంది, మరియు వ్యక్తిత్వం రూపుదాల్చుతుంది.',
    'కొంతమంది హృదయపూర్వకమైన, నిజాయితీ గల, శక్తివంతమైన పురుషులు మరియు స్త్రీలు ఒక సంవత్సరంలో చేసే కార్యం, శతాబ్దకాలం పాటు చేసే జనసమూహం కంటే ఎక్కువ ఫలితాలను ఇస్తుంది.',
    'జీవిత రహస్యం ఆనందంలో కాదు, అనుభవం ద్వారా విద్యలో ఉంది.',
    'ప్రతిఫలం ఆశించినపుడే అనుబంధం కలుగుతుంది.',
    'చెదరిపోవడం కంటే, ఉపయోగించి నశించడం మేలు.',
    'నేను వృద్ధుడిగా మారుతున్న కొద్దీ, సర్వం పురుషత్వంలోనే ఉందని నాకు అనిపిస్తోంది.',
    'మంచిగా ఉండటం, మంచిని చేయడం — ఇదే ధర్మం యొక్క సారాంశం.',
    'తనను జయించినవాడు సర్వం జయించినవాడవుతాడు.',
    'అన్ని దుఃఖాలు ఆస్తి పట్ల ఆసక్తి నుండి వస్తాయి, అన్ని బాధలు కోరిక నుండి ఉద్భవిస్తాయి.',
    'ఇతరుల సేవలో తమ శరీరాలు నశించినవారు ధన్యులు.',
    'మనసు తీవ్రంగా ఆసక్తి కలిగి ఉంటే, సమస్తం సాధించగలిగినదే.',
    'ఆత్మకు లింగభేదం లేదా అపూర్ణత లేవు.',
    'మతం అనేది ఆత్మసాక్షాత్కారం; మాటలు కాదు, సిద్ధాంతాలు కాదు, సిద్ధాంతాలు కూడా కాదు.',
    'మనము ఏమిటో దానికి మనమే బాధ్యత వహించాలి, మనకు కావలసిన రూపాన్ని మనమే సృష్టించుకునే శక్తి మనకుంది.',
    'ఎంతటి మూర్ఖుడైనా తన శ్రద్ధను పెట్టినప్పుడు జ్ఞానవంతుడిగా మారగలడు.',
    'విచారాలు నిన్ను ఎక్కడికి తీసుకెళ్తాయో అక్కడికి వెళ్లడానికి ధైర్యం చూపించు, స్వేచ్ఛగా ఉండడానికి ధైర్యం చూపించు.',
    'పనిని పూజగా భావించు.',
    'భయంకరమైనదాన్ని ఎదుర్కో, ధైర్యంగా ఎదుర్కో.',
    'ఏకాగ్రతతో కూడిన సంకల్పం, తన సాధన కోసం సర్వస్వం అర్పించగలిగితే, దానికి ఎదురు నిలవగల శక్తి ఏదీ లేదు.',
    'ఇతరులలో మీరే అనుభూతి చెందడం నేర్చుకోండి.',
    'అనియంత్రితమైన మరియు మార్గదర్శనం లేని మనస్సు నిన్ను ఎప్పటికీ దిగజారుస్తుంది.',
    'మన హృదయాల్లో, ప్రతి జీవిలో దేవుని చూడలేకపోతే, ఆయనను ఎక్కడ వెతుకుతాం?',
    'సర్వశక్తి నీలోనే ఉంది; నీవు బలహీనుడని నమ్మకుము.',
    'అస్తిత్వం యొక్క సంపూర్ణ రహస్యం భయాన్ని విడిచిపెట్టడంలోనే ఉంది.',
    'నీ స్వంత పాదాలపై నిలబడి, నిజమైన మనిషిగా మారు.',
    'ఈ జీవితం ఒక కఠినమైన నిజం; ధైర్యంగా దానిని ఎదుర్కొనండి.',
    'మనిషి యొక్క నిజమైన మహత్త్వం అతని ఆత్మనివేదన సామర్థ్యంలో ఉంది.',
    'ఏకత్వాన్ని గ్రహించినవాడు సర్వత్రా దేవుని దర్శిస్తాడు.',
    'పాత్రిత్వం బుద్ధికంటే శ్రేష్ఠమైనది.',
    'మీరు నిమగ్నంగా ఉన్నప్పుడు ప్రతిదీ సులభమే.',
    'మీరు భయపడిన క్షణం, మీరు బంధించబడ్డారు.',
    'సత్యం వెయ్యి విధాలుగా చెప్పబడవచ్చు, అయినప్పటికీ ప్రతి ఒక్కటి నిజమే కావచ్చు.',
    'విద్య అనేది మీ మెదడులో నింపబడే సమాచారం కాదు, జీవన నిర్మాణం, మనుష్యుల రూపకల్పన, వ్యక్తిత్వ నిర్మాణం కోసం ఆలోచనల సమాహారం.',
    'దేశానికి అవసరం శక్తి, శక్తి మాత్రమే.',
    'ఒక ఆలోచన మనసును పూర్తిగా ఆక్రమించినప్పుడు, అది వాస్తవిక భౌతిక లేదా మానసిక స్థితిగా మారుతుంది.',
    'మీరు ఏ పని చేసినా, దానిలో మీ హృదయం, మనసు, ఆత్మను పూర్తిగా నిమగ్నం చేయండి.',
    'ప్రతి ప్రాణిలోను భగవంతుని సమానంగా చూసేవాడు మాత్రమే నిజంగా చూస్తాడు.',
    'ఈ విశ్వం ఒక అనంతమైన సత్తా.',
    'మీ స్వరూపాన్ని ధైర్యంగా ఆచరించండి.',
    'స్వేచ్ఛ ఆత్మ యొక్క గానం.',
    'సర్వ జ్ఞానం ఆత్మలోనే ఉంది.',
    'ఈ సమస్త ప్రపంచం భగవంతుని ఆటస్థలం.',
    'ఎవరినీ లేదా ఏదినీ ఎదురుచూడకండి. మీకు సాధ్యమైనది చేయండి, ఎవరి మీదా ఆశ పెట్టుకోకండి.',
    'ఇతరులను ఆధీనంలో ఉంచడానికి కాకుండా, వారికి సహాయం చేయడానికి జీవించండి.',
    'మీరు జీవించి ఉన్నందుకు మరియు పనిచేయగలిగే స్థితిలో ఉన్నందుకు కృతజ్ఞతతో ఉండండి.',
    'మీ దైవత్వాన్ని వ్యక్తీకరించండి.',
  ],

  [
    Article(
        heading: 'ప్రపంచ ధర్మ సభకు ఉద్దేశం',
        body: 'అమెరికాలోని సోదరీమణులు మరియు సోదరులారా, మీరు మాకు అందించిన ఆత్మీయ మరియు స్నేహపూర్వక స్వాగతానికి స్పందిస్తూ నా హృదయాన్ని అపార ఆనందంతో నింపుతుంది. ప్రపంచంలోని అత్యంత ప్రాచీన మఠాల ఆజ్ఞలో మీకు కృతజ్ఞతలు తెలుపుతున్నాను; ధర్మాల తల్లి పేరుతో మీకు కృతజ్ఞతలు తెలుపుతున్నాను; మరియు అన్ని తరగతులు, పंथాల హిందువుల కోట్ల కొలమానాల పేరుతో మీకు కృతజ్ఞతలు తెలుపుతున్నాను. \n\nఈ వేదికపై ఉన్న కొన్ని ప్రసంగకర్తలకు కూడా నా కృతజ్ఞతలు, వారు తూర్పు నుండి వచ్చిన ప్రతినిధుల గురించి చెప్పినప్పుడు, ఈ దూర దేశాల వ్యక్తులు భిన్న భూములకు సహనం అనే ఆలోచనను తీసుకువచ్చే గౌరవాన్ని పొందవచ్చు అని చెప్పారు. సహనం మరియు విశ్వవ్యాప్త స్వీకరణను ప్రపంచానికి బోధించిన ధర్మానికి నేను గర్వంగా చెందుతున్నాను. మేము కేవలం విశ్వసహనం మీద మాత్రమే నమ్మకం ఉంచడం కాదు, మేము అన్ని ధర్మాలను సత్యంగా స్వీకరిస్తాము. నేను అన్ని మతాలు మరియు అన్ని దేశాల persecuted మరియు శరణార్థులను ఆశ్రయించిన ఒక దేశానికి చెందినందుకు గర్వంగా ఉన్నాను. రోమన్ అణచివేత వల్ల వారి పవిత్ర దేవాలయం విరిగిపోతున్న సంవత్సరంలో దక్షిణ భారతదేశానికి వచ్చిన ఇశ్రాయేలీయుల శుద్ధమైన మిగతా భాగాన్ని మా గుండెల్లో సేకరించినందుకు గర్వంగా ఉన్నాను. గొప్ప జోరాస్ట్రియన్ జాతి మిగతా భాగాన్ని ఆశ్రయించిన మరియు ఇంకా పెంపొందిస్తున్న మతానికి చెందినందుకు గర్వంగా ఉన్నాను. నేను మీకు, సోదరులారా, నా చిన్ననాటి నుండి నేను పునరావృతం చేసిన ఒక గీతంలోని కొన్ని పంక్తులను ఉటంకిస్తున్నాను, ఇది ప్రతి రోజు కోట్లాది మానవులచే పునరావృతం అవుతుంది: “వివిధ ప్రదేశాల్లోని వనరుల నుండి ఉద్భవించిన వివిధ నదులు సముద్రంలో తమ నీటిని కలిపినట్లే, ఓ ప్రభువా, మానవులు వివిధ ప్రవర్తనల ద్వారా తీసుకునే వివిధ మార్గాలు, అవి ఎలా ఉన్నా, వక్రంగా లేదా సూటిగా, అన్నీ నీ వైపు నడుస్తున్నాయి.” \n\n ఈ ప్రస్తుత సమావేశం, ఇది ఎప్పుడూ నిర్వహించిన అత్యంత మహోన్నత సమ్మేళనాలలో ఒకటి, ఇది ఒక రక్షణ, ప్రపంచానికి గీతలో ఉపదేశించిన అద్భుత సిద్ధాంతానికి ఒక ప్రకటన: “ఎవరైనా నాకు వస్తే, ఏ రూపంలోనైనా, నేను అతనిని చేరుకుంటాను; అన్ని మనుషులు చివరికి నన్ను చేరుకునే మార్గాలలో పోరాడుతున్నారు.” పక్షపాతం, కఠినత్వం, మరియు దాని భయంకరమైన వారసుడు, ఉగ్రవాదం, ఈ అందమైన భూమిని చాలా కాలంగా ఆక్రమించిఉంది. వారు భూమిని హింసతో నింపారు, తరచూ మానవ రక్తంతో తడిపారు, నాగరికతను నాశనం చేశారు మరియు మొత్తం జాతులను నిరాశలోకి పంపించారు. ఈ భయంకరమైన రాక్షసులు లేకపోతే, మానవ సమాజం ఇప్పుడు ఉన్న స్థితికి కంటే చాలా ముందుకు వెళ్లి ఉండేది. కానీ వారి కాలం వచ్చింది; ఈ సదస్సుకు గౌరవంగా ఈ ఉదయం మోగిన గంట, అన్ని ఉగ్రవాదానికి, కత్తి లేదా పెన్నుతో జరిగే అన్ని persecutingలకు, మరియు ఒకే లక్ష్యాన్ని చేరుకునే వ్యక్తుల మధ్య ఉన్న అన్ని దయారహిత భావాలకు మరణ గంటగా ఉండాలని నేను తీవ్రంగా ఆశిస్తున్నాను.'
    ),
    Article(
        heading: 'కర్మ మరియు దాని పాత్రపై ప్రభావం',
        body: 'కర్మ అనే పదం సంస్కృతంలో క్రీ (Kri) నుండి ఉద్భవించింది, అంటే చేయడం; అన్ని చర్యలు కర్మ. సాంకేతికంగా, ఈ పదం చర్యల ఫలితాలను కూడా సూచిస్తుంది. మెటాఫిజిక్స్‌తో సంబంధం కలిగి, ఇది కొన్ని సార్లు మన గత చర్యలు కారణమైన ఫలితాలను సూచిస్తుంది. కానీ కర్మ-యోగంలో, కర్మ అనే పదాన్ని పని అని అర్థం చేసుకోవాలి. మానవుల లక్ష్యం జ్ఞానం. ఇది తూర్పు తత్త్వశాస్త్రం మన ముందుంచిన ఒకే ఒక్క ఆదర్శం. ఆనందం మానవుల లక్ష్యం కాదు, కానీ జ్ఞానం. ఆనందం మరియు సంతోషం ఒక రోజు ముగుస్తాయి. ఆనందం లక్ష్యం అని భావించడం తప్పు. ప్రపంచంలో మనకు ఉన్న అన్ని దుఃఖాల కారణం, మనుషులు మూర్ఖంగా ఆనందాన్ని సాధించాల్సిన ఆదర్శంగా భావించడం. ఒక సమయంలో మనిషి ఆనందం కాదు, జ్ఞానం వైపు వెళ్ళుతున్నాడని గ్రహిస్తాడు, మరియు సుఖం మరియు దుఖం రెండూ గొప్ప ఉపాధ్యాయులుగా ఉంటాయి, మరియు అతను చెడు నుండి కూడా మంచి నుండి ఎంతగానో నేర్చుకుంటాడు. సుఖం మరియు దుఖం అతని ఆత్మ ముందు గడిచేటప్పుడు, అవి వేర్వేరు చిత్రాలను కలిగి ఉంటాయి, మరియు ఈ కలిపిన ప్రభావాల ఫలితం మనిషి "చరిత్ర" అని పిలువబడుతుంది. మీరు ఏ మనిషి యొక్క చరిత్రను తీసుకుంటే, అది నిజంగా ధోరణుల సమాహారం, అతని మనస్సు యొక్క వక్రత యొక్క మొత్తం; మీరు misery మరియు happiness రెండూ ఆ చరిత్రను రూపొందించడంలో సమాన భాగస్వాములు అని కనుగొంటారు. మంచి మరియు చెడు చరిత్రను మ mould చేయడంలో సమానంగా భాగస్వామ్యం చేస్తాయి, మరియు కొన్ని సందర్భాల్లో misery ఆనందం కంటే గొప్ప ఉపాధ్యాయుడు. ప్రపంచం ఉత్పత్తి చేసిన మహానుభావుల అధ్యయనంలో, నేను చెప్పగలను, చాలా సందర్భాల్లో, దుఃఖం ఆనందం కంటే ఎక్కువగా బోధించింది, దారిద్ర్యం సంపద కంటే ఎక్కువగా బోధించింది, పొడవైన దెబ్బలు ప్రశంస కంటే ఎక్కువగా వారి అంతర అగ్ని వెలికితీసింది. \n\nఇప్పుడు ఈ జ్ఞానం మానవునిలో స్వభావికంగా ఉంది. ఎలాంటి జ్ఞానం బయట నుండి రాదు; ఇది అంతా అంతర్గతం. మనం ఒక వ్యక్తి "తెలుసుకుంటాడు" అని చెప్పినప్పుడు, అది కఠినమైన మానసిక భాషలో, అతను "కనుగొంటాడు" లేదా "వెలగిస్తాడు" అని ఉండాలి; ఒక వ్యక్తి "కలుస్తాడు" అనేది వాస్తవానికి అతను "కనుగొంటాడు", తన స్వంత ఆత్మ యొక్క కవచాన్ని తీసివేయడం ద్వారా, అది అనంత జ్ఞానానికి ఒక ఖనిజం. \n\nమనం న్యూటన్ గ్రావిటేషన్‌ను కనుగొన్నాడని చెప్పుతాము. అది ఎక్కడైనా మూలలో అతని కోసం వేచి ఉన్నదా? అది అతని స్వంత మనసులో ఉంది; సమయం వచ్చింది మరియు అతను దాన్ని కనుగొన్నాడు. ప్రపంచం ఎప్పుడూ పొందిన అన్ని జ్ఞానం మన మనసులోనే ఉంది; విశ్వం యొక్క అనంత గ్రంథాలయం మీ స్వంత మనసులో ఉంది. బాహ్య ప్రపంచం కేవలం సూచన, మీ స్వంత మనసును అధ్యయనం చేయడానికి ప్రేరణను అందించే సందర్భం మాత్రమే, కానీ మీ అధ్యయనానికి ఆబ్జెక్ట్ ఎప్పుడూ మీ స్వంత మనసే. ఒక ఆపిల్ పడటం న్యూటన్‌కు సూచనను ఇచ్చింది, మరియు అతను తన స్వంత మనసును అధ్యయనం చేశాడు. అతను తన మనసులోని అన్ని గత ఆలోచనల అనుసంధానాలను పునఃవ్యవస్థీకరించి, వాటిలో ఒక కొత్త అనుసంధానాన్ని కనుగొన్నాడు, దీనిని మేము ఆకర్షణ శాస్త్రం అని పిలుస్తాము. అది ఆపిల్‌లో లేదా భూమి కేంద్రంలో ఏదీ లేదు. \n\nఅందువల్ల, అన్ని జ్ఞానం, భౌతిక లేదా ఆధ్యాత్మిక, మానవ మనసులోనే ఉంది. చాలా సందర్భాల్లో ఇది కనుగొనబడదు, కానీ కప్పబడినట్లుగా ఉంటుంది, మరియు కప్పు నెమ్మదిగా తీసివేయబడుతున్నప్పుడు, "మేము నేర్చుకుంటున్నాము" అని మనం అంటాము, మరియు జ్ఞానానికి పురోగతి ఈ కప్పు తీసివేత ప్రక్రియ యొక్క పురోగతితో జరుగుతుంది. ఈ కప్పు తీసివేయబడుతున్న వ్యక్తి ఎక్కువగా తెలిసిన వ్యక్తి, ఈ కప్పు బాగా ఉండే వ్యక్తి అజ్ఞాని, మరియు ఇది పూర్తిగా తీసివేయబడిన వ్యక్తి సమస్తజ్ఞుడు, సర్వజ్ఞుడు. సమస్తజ్ఞులు ఉన్నారు, మరియు, నేను నమ్ముతున్నాను, ఇంకా ఉండబోతున్నారు; మరియు రాబోయే చక్రాలలో వారి సంఖ్య అనేకంగా ఉండనుంది. ఒక మణికట్టు లో అగ్నికి సమానంగా, జ్ఞానం మనసులో ఉంది; సూచన అనేది దాన్ని బయటకు తీసుకురావడానికి జరిగే రుద్రత. అందువల్ల మన భావాలు మరియు చర్యలతో — మన కన్నీళ్లు మరియు మన నవ్వులు, మన ఆనందాలు మరియు మన దుఖాలు, మన ఏడుపు మరియు మన నవ్వు, మన శపథాలు మరియు మన ఆశీర్వాదాలు, మన స్తుతులు మరియు మన నిందలు — ఈ ప్రతీది మనలోని మన స్వయాన్ని శాంతిగా అధ్యయనం చేస్తే, మనలోని అంతర్గతంగా ఎన్నో కొట్టింపుల ద్వారా వెలువడినట్లు కనుగొనవచ్చు. ఫలితం ఏమిటంటే, మనం ఏమిటో అదే. ఈ అన్ని కొట్టింపులు కలిపి కర్మ అని పిలువబడతాయి — పని, చర్య. ఆత్మకు ఇచ్చే ప్రతి మానసిక మరియు శారీరక కొట్టింపు, దాని నుండి అగ్ని వెలువడినట్లు, మరియు దాని స్వంత శక్తి మరియు జ్ఞానం కనుగొనబడినట్లు, అది కర్మ, ఈ పదం విస్తృతమైన అర్థంలో ఉపయోగించబడుతుంది. అందువల్ల, మేము ఎప్పుడూ కర్మ చేస్తున్నాము. నేను మీతో మాట్లాడుతున్నాను: అది కర్మ. మీరు వినుతున్నారు: అది కర్మ. మేము శ్వాసిస్తున్నాము: అది కర్మ. మేము నడుస్తున్నాము: కర్మ. మనం చేసే ప్రతీది, శారీరకంగా లేదా మానసికంగా, కర్మ. ఇది మనపై తన ముద్రలను వదులుతుంది. \n\nకొన్ని పనులు, అనగా, అనేక చిన్న పనుల సమాహారం, మొత్తం. మనం సముద్రతీరంలో నిలబడి, అలలు చెక్కలపై కొట్టుకుంటున్న శబ్దాన్ని వినేటప్పుడు, అది ఎంత గొప్ప శబ్దమో అనుకుంటాము, కానీ ఒక అల అనేక చిన్న అలల సమాహారంగా ఉండటం మనకు తెలుసు. ఈ ప్రతి అల ఒక శబ్దాన్ని చేస్తుంది, కానీ మనం దాన్ని పట్టించుకోలేము; అవి పెద్ద సమాహారంగా మారినప్పుడు మాత్రమే మనం వినగలుగుతాము. అలాగే, హృదయపు ప్రతి కొట్టుకు ఒక పని. కొన్ని రకాల పనులను మనం అనుభవిస్తాము మరియు అవి మనకు స్పష్టంగా కనిపిస్తాయి; అవి ఒక పక్క, అనేక చిన్న పనుల సమాహారం. మీరు నిజంగా ఒక వ్యక్తి స్వభావాన్ని అంచనా వేయాలనుకుంటే, అతని గొప్ప ప్రదర్శనలను చూడకండి. ప్రతి మూర్ఖుడు ఒక సమయంలో లేదా మరొక సమయంలో వీరుడవ్వవచ్చు. ఒక మనిషి తన సాధారణ కార్యాలను చేస్తుంటే చూడండి; అవి నిజంగా ఒక గొప్ప మనిషి యొక్క నిజమైన స్వభావాన్ని మీకు తెలియజేస్తాయి. గొప్ప సందర్భాలు కనీసం మానవులలో కొంత గొప్పతనాన్ని ప్రేరేపిస్తాయి, కానీ ఎక్కడ ఉన్నా, ఎప్పుడూ గొప్ప స్వభావం కలిగిన వ్యక్తి మాత్రమే నిజమైన గొప్ప మనిషి. \n\nస్వభావంపై కర్మ యొక్క ప్రభావం మానవుడు ఎదుర్కొనే అత్యంత శక్తివంతమైన శక్తి. మనిషి ఒక కేంద్రం వంటిది, మరియు విశ్వంలోని అన్ని శక్తులను తన వైపు ఆకర్షిస్తున్నాడు, మరియు ఈ కేంద్రంలో వాటిని అన్ని విలీనం చేసి, తిరిగి పెద్ద ప్రవాహంలో పంపుతున్నాడు. అలాంటి కేంద్రం నిజమైన మనిషి — శక్తివంతుడు, సర్వగ్ఞుడు — మరియు అతను మొత్తం విశ్వాన్ని తన వైపు ఆకర్షిస్తున్నాడు. మంచి మరియు చెడు, దుఃఖం మరియు ఆనందం, అన్నీ ఆయన వైపు పరుగులు తీస్తున్నాయి మరియు ఆయన చుట్టూ cling అవుతున్నాయి; వాటిలోనుంచి ఆయన ధర్మం అనే శక్తివంతమైన ప్రవాహాన్ని రూపొందించి, దానిని బయటకు విసరిస్తాడు. ఆయన ఏదైనా ఆకర్షించగల శక్తిని కలిగి ఉన్నట్లుగా, దానిని బయటకు విసరగల శక్తి కూడా ఆయనకు ఉంది.\n\nప్రపంచంలో మనం చూసే అన్ని చర్యలు, మానవ సమాజంలో జరిగే అన్ని కదలికలు, మన చుట్టూ ఉన్న అన్ని పనులు, ఇవన్నీ కేవలం ఆలోచన యొక్క ప్రదర్శన, మానవ సంకల్పం యొక్క ప్రదర్శన. యంత్రాలు లేదా పరికరాలు, నగరాలు, నావలు లేదా యుద్ధ నావలు, ఇవన్నీ కేవలం మానవ సంకల్పం యొక్క ప్రదర్శన; మరియు ఈ సంకల్పం ధర్మం ద్వారా సృష్టించబడుతుంది, మరియు ధర్మం కర్మ ద్వారా తయారవుతుంది. కర్మ ఎలా ఉంటే, సంకల్పం కూడా అలా ఉంటుంది. ప్రపంచం ఉత్పత్తి చేసిన శక్తివంతులైన పురుషులు అందరూ అద్భుతమైన కార్మికులు - ప్రపంచాలను తిరగరాయగల శక్తివంతమైన సంకల్పాలతో కూడిన విస్తృత ఆత్మలు. ఈ సంకల్పాలు వారు నిరంతర కృషి ద్వారా, యుగాలుగా, యుగాలుగా పొందినవి. బుద్ధ లేదా యేసు వంటి అద్భుతమైన సంకల్పం ఒకే జీవితంలో పొందలేము, ఎందుకంటే వారి తండ్రులు ఎవరో మనకు తెలుసు. మానవత్వానికి మంచిది కోసం వారి తండ్రులు ఒక్క మాట కూడా మాట్లాడినట్లు తెలియదు. జోసెఫ్ వంటి లక్షలాది కార్పెంటర్లు వెళ్లిపోయారు; లక్షలాది ఇంకా జీవిస్తున్నారు. బుద్ధుని తండ్రి వంటి లక్షలాది చిన్న రాజులు ఈ ప్రపంచంలో ఉన్నారు. ఇది కేవలం వారసత్వ ప్రసరణ మాత్రమే అయితే, ఈ చిన్న రాజు, అతని స్వంత సేవకులు కూడా అతన్ని అనుసరించకపోవచ్చు, ఎలా ఈ కొడుకును ఉత్పత్తి చేశాడు, దీనిని అర్ధ ప్రపంచం పూజిస్తుంది? కార్పెంటర్ మరియు అతని కొడుకు మధ్య ఉన్న తేడాను ఎలా వివరించగలరు, అనేక మానవులు దేవుడిగా పూజించే? ఇది వారసత్వ సిద్ధాంతం ద్వారా పరిష్కరించబడదు. బుద్ధుడు మరియు యేసు ప్రపంచంపై విసిరిన మహత్తర ఇచ్ఛ శక్తి ఎక్కడి నుండి వచ్చింది? ఈ శక్తి యొక్క సమాహారం ఎక్కడి నుండి వచ్చింది? ఇది యుగాలుగా అక్కడే ఉండి, నిరంతరం పెరుగుతూ, బుద్ధుడు లేదా యేసు రూపంలో సమాజంపై విరుచుకుపడే వరకు పెరిగింది, ఇప్పటికీ ప్రస్తుత కాలానికి చేరుకుంది.\n\nఇది అన్నీ కర్మ, పని ద్వారా నిర్ణయించబడుతుంది. ఎవరు సంపాదించకుండానే ఏమీ పొందలేరు. ఇది శాశ్వతమైన చట్టం. మనం కొన్ని సమయాల్లో ఇది అలా కాదు అనుకుంటాం, కానీ దీర్ఘకాలంలో మనం దీనిపై నమ్మకం కలిగి ఉంటాము. ఒక వ్యక్తి తన జీవితంతా ధనానికి పోరాడవచ్చు; అతను వేల మందిని మోసం చేయవచ్చు, కానీ చివరికి అతను ధనవంతుడయ్యేందుకు అర్హత కలిగి లేదని తెలుసుకుంటాడు, మరియు అతని జీవితం అతనికి కష్టంగా మరియు ఇబ్బందిగా మారుతుంది. మనం శారీరక ఆనందం కోసం వస్తువులను సేకరించడంలో కొనసాగవచ్చు, కానీ మనం సంపాదించినది మాత్రమే నిజంగా మనది. ఒక మూర్ఖుడు ప్రపంచంలోని అన్ని పుస్తకాలను కొనుగోలు చేయవచ్చు, అవి అతని గ్రంథాలయంలో ఉంటాయి; కానీ అతను చదవగలిగేది కేవలం అతను అర్హత కలిగి ఉన్నవి మాత్రమే; మరియు ఈ అర్హత కర్మ ద్వారా ఉత్పత్తి అవుతుంది. మన కర్మ మనకు ఏమి అర్హత ఉందో మరియు మనం ఏమి గ్రహించగలమో నిర్ణయిస్తుంది. మనం ఏమిటి అనే దానికి మనం బాధ్యులం; మరియు మనం మనకు కావాలనుకునే ఏదైనా, మనం మనలను తయారు చేసుకునే శక్తిని కలిగి ఉన్నాము. మనం ఇప్పుడు ఉన్నది మన గత చర్యల ఫలితంగా ఉంటే, భవిష్యత్తులో మనం కావాలనుకునేది మన ప్రస్తుత చర్యల ద్వారా ఉత్పత్తి చేయబడవచ్చు; కాబట్టి మనం ఎలా చర్య చేయాలో తెలుసుకోవాలి. మీరు చెప్పగలరు, "కార్యాన్ని ఎలా చేయాలో నేర్చుకోవడం ఏమిటి? ఈ ప్రపంచంలో ప్రతి ఒక్కరు ఏదో ఒక విధంగా పని చేస్తారు." కానీ మన శక్తులను వ్యర్థం చేసుకోవడం అనే విషయం ఉంది. కర్మ-యోగం గురించి, గీత చెబుతుంది, ఇది చాతుర్యంతో మరియు శాస్త్రంగా పని చేయడం; పని చేయడం ఎలా అనేది తెలుసుకుంటే, అత్యంత ఫలితాలను పొందవచ్చు. మీరు గుర్తుంచుకోవాలి, అన్ని పనులు మనసులో ఇప్పటికే ఉన్న శక్తిని వెలికి తీసేందుకు, ఆత్మను మేల్కొల్పడానికి మాత్రమే. ప్రతి మనిషిలో శక్తి ఉంది, అలాగే జ్ఞానం కూడా ఉంది; వివిధ పనులు వాటిని వెలికి తీసేందుకు, ఈ మహానుభావులను మేల్కొల్పేందుకు తాకిడిలా ఉన్నాయి. \n\nమనిషి వివిధ ఉద్దేశాలతో పనిచేస్తాడు. ఉద్దేశం లేకుండా పని ఉండదు. కొంత మంది ఖ్యాతి పొందాలనుకుంటారు, అందుకే వారు ఖ్యాతి కోసం పనిచేస్తారు. మరికొందరు డబ్బు కావాలనుకుంటారు, వారు డబ్బు కోసం పనిచేస్తారు. మరికొందరు శక్తి పొందాలనుకుంటారు, వారు శక్తి కోసం పనిచేస్తారు. మరికొందరు స్వర్గం పొందాలనుకుంటారు, వారు అదే కోసం పనిచేస్తారు. మరికొందరు చనిపోయినప్పుడు పేరు వదిలేయాలని కోరుకుంటారు, చైనాలో ఉన్నట్లుగా, అక్కడ ఎవరూ చనిపోయే వరకు టైటిల్ పొందరు; మరియు అది, చివరికి, మనతో పోలిస్తే మంచి మార్గం. అక్కడ ఒక మనిషి చాలా మంచి పని చేస్తే, వారు అతని చనిపోయిన తండ్రికి లేదా తాతకు అర్హత ఇచ్చి, నోబిలిటీ టైటిల్ ఇస్తారు. కొంత మంది అందుకోసం పనిచేస్తారు. కొన్ని మోహమ్మదీయ పంథాల అనుచరులు, వారు మరణించినప్పుడు తమ కోసం పెద్ద సమాధి నిర్మించేందుకు జీవితాంతం పనిచేస్తారు. ఒక పంథాలో, ఒక పిల్లవాడు జన్మించిన వెంటనే, దానికి సమాధి సిద్ధం చేయబడుతుంది; అది వారికి అత్యంత ముఖ్యమైన పని, మరియు సమాధి ఎంత పెద్దది, అంత అందమైనది, ఆ వ్యక్తి ఎంత మంచి స్థితిలో ఉన్నాడో అంచనా వేయబడుతుంది. మరికొందరు పుణ్యార్థం పనిచేస్తారు; అన్ని రకాల దురాచారాలు చేస్తారు, తరువాత ఒక దేవాలయాన్ని నిర్మిస్తారు, లేదా పూజారులకు ఏదైనా ఇవ్వడం ద్వారా వారిని కొనుగోలు చేసి, స్వర్గానికి పాస్‌పోర్ట్ పొందుతారు. ఈ రకమైన దాతృత్వం వారిని శుద్ధి చేస్తుందని, వారు తమ పాపాల కారణంగా శిక్షించబడకుండా తప్పించుకుంటారని భావిస్తారు. ఈ విధంగా, పని చేయడానికి వివిధ ప్రేరణలు ఉన్నాయి. \n\nపనికి పనికోసం చేయండి. ప్రతి దేశంలో నిజంగా భూమి యొక్క ఉప్పు అయిన కొందరు ఉన్నారు, వారు కేవలం పనికి పనిగా పనిచేస్తారు, పేరు, ఖ్యాతి లేదా స్వర్గానికి వెళ్లడం గురించి ఆలోచించరు. వారు మంచి ఫలితాలు వస్తాయని నమ్మి పనిచేస్తారు. మరికొందరు పేదలకు మంచి చేస్తారు మరియు మానవత్వానికి మరింత ఉన్నతమైన ఉద్దేశ్యాల నుండి సహాయం చేస్తారు, ఎందుకంటే వారు మంచి చేయడంలో విశ్వాసం కలిగి ఉంటారు మరియు మంచి ప్రేమిస్తారు. పేరు మరియు ఖ్యాతి కోసం ఉద్దేశ్యం సాధారణంగా తక్షణ ఫలితాలను తీసుకురావదు; అవి మనకు వయస్సు వచ్చినప్పుడు మరియు జీవితం ముగించడానికి దగ్గరగా ఉన్నప్పుడు వస్తాయి. ఒక వ్యక్తి స్వార్థం లేకుండా పనిచేస్తే, అతను ఏమీ పొందడు కాదా? అవును, అతను అత్యుత్తమాన్ని పొందుతాడు. స్వార్థరహితత్వం ఎక్కువగా లాభదాయకంగా ఉంటుంది, కానీ ప్రజలకు దీన్ని అనుసరించడానికి సహనం ఉండదు. ఇది ఆరోగ్యానికి సంబంధించి కూడా ఎక్కువ లాభదాయకంగా ఉంటుంది. ప్రేమ, సత్యం, మరియు నిర్భయత కేవలం నైతిక మాటలు కాదు, అవి మన అత్యున్నత ఆలోచనను నిర్మిస్తాయి, ఎందుకంటే వాటిలో శక్తి యొక్క అద్భుతమైన ప్రదర్శన ఉంది. మొదటగా, ఏ వ్యక్తి ఐదు రోజుల పాటు, లేదా ఐదు నిమిషాల పాటు, ఏ స్వార్థం లేకుండా, భవిష్యత్తు, స్వర్గం, శిక్ష లేదా ఇలాంటి ఏదైనా గురించి ఆలోచించకుండా పని చేయగలడు, అతనిలో ఒక శక్తివంతమైన నైతిక మహానుభావంగా మారే సామర్థ్యం ఉంది. ఇది చేయడం కష్టమైనది, కానీ మన హృదయాలలో దాని విలువ మరియు అది తెచ్చే మంచి గురించి మనకు తెలుసు. ఇది శక్తి యొక్క అత్యంత ప్రదర్శన - ఈ అద్భుతమైన నియంత్రణ; స్వీయ నియంత్రణ అన్ని బాహ్య చర్యల కంటే ఎక్కువ శక్తి యొక్క ప్రదర్శన. నాలుగు గుర్రాలను కలిగిన ఒక రథం నియంత్రణ లేకుండా కొండ కింద పరుగెత్తవచ్చు, లేదా కోచ్‌మెన్ గుర్రాలను నియంత్రించవచ్చు. శక్తి యొక్క గొప్ప ప్రదర్శన ఏది, వాటిని విడిచిపెట్టడం లేదా వాటిని పట్టుకోవడం? గాలిలో పరిగెడుతున్న కాణన్ బంతి చాలా దూరం వెళ్లి పడుతుంది. మరోటి గోడకు తాకి తన పయనంలో ఆపబడుతుంది, మరియు ఆ తాకుడు తీవ్ర ఉష్ణాన్ని ఉత్పత్తి చేస్తుంది. స్వార్థం ఉన్న ప్రేరణతో బయటకు వెళ్లే అన్ని శక్తి వ్యర్థం అవుతుంది; అది మీకు శక్తిని తిరిగి ఇవ్వదు; కానీ అడ్డుకుంటే, అది శక్తి అభివృద్ధికి దారితీస్తుంది. ఈ స్వీయ నియంత్రణ ఒక శక్తివంతమైన ఇచ్ఛను, క్రీస్తు లేదా బుద్ధుడిని తయారు చేసే స్వభావాన్ని ఉత్పత్తి చేస్తుంది. మూర్ఖులు ఈ రహస్యాన్ని తెలియకపోతారు; అయినప్పటికీ, వారు మానవత్వాన్ని పాలించాలనుకుంటారు. ఒక మూర్ఖుడు పని చేస్తే మరియు వేచి ఉంటే, అతను మొత్తం ప్రపంచాన్ని పాలించవచ్చు. అతను కొన్ని సంవత్సరాలు వేచి ఉండనివ్వండి, ఆ పాలన యొక్క మూర్ఖమైన ఆలోచనను అడ్డుకోండి; మరియు ఆ ఆలోచన పూర్తిగా పోయినప్పుడు, అతను ప్రపంచంలో ఒక శక్తిగా మారుతుంది. మనలో చాలా మంది కొన్ని సంవత్సరాల కంటే మించి చూడలేరు, కొన్ని జంతువులు కొన్ని అడుగుల కంటే మించి చూడలేకపోతాయి. కేవలం కొంచెం కుదుటి చుట్టూ — అది మన ప్రపంచం. మేము మించిపోయే దృష్టిని కలిగి ఉండటానికి సహనం లేదు, అందువల్ల మేము అహంకారిగా మరియు దుష్టంగా మారుతాము. ఇది మన బలహీనత, మన శక్తి లేమి.\n\nఅత్యంత తక్కువ స్థాయి పనులను తక్కువగా చూడకూడదు. మంచి మరియు ఖ్యాతి కోసం, మెరుగైనది తెలియని వ్యక్తి స్వార్థం కోసం పనిచేయనివ్వండి; కానీ ప్రతి ఒక్కరూ ఎప్పుడూ ఉన్నతమైన మరియు ఉన్నతమైన ఉద్దేశాల వైపు ప్రయత్నించాలి మరియు వాటిని అర్థం చేసుకోవాలి. "పనిచేయడానికి మనకు హక్కు ఉంది, కానీ దాని ఫలాలపై కాదు:" ఫలాలను విడిచేయండి. ఫలాల గురించి ఎందుకు ఆందోళన చెందాలి? మీరు ఒక వ్యక్తికి సహాయం చేయాలనుకుంటే, ఆ వ్యక్తి మీపై ఎలా ఉండాలి అనే దానిపై ఎప్పుడూ ఆలోచించకండి. మీరు గొప్ప లేదా మంచి పని చేయాలనుకుంటే, ఫలితం ఏమిటి అని ఆలోచించడానికి కష్టపడవద్దు. \n\nఈ పనిలో ఈ ఆదర్శానికి ఒక కష్టమైన ప్రశ్న ఉత్పన్నమవుతుంది. తీవ్ర కార్యకలాపం అవసరం; మేము ఎప్పుడూ పని చేయాలి. పని లేకుండా ఒక నిమిషం కూడా జీవించలేము. అప్పుడు విశ్రాంతికి ఏమవుతుంది? ఇక్కడ జీవన పోరాటం యొక్క ఒక వైపు ఉంది — పని, ఇందులో మేము వేగంగా చుట్టుకుంటున్నాము. మరియు ఇక్కడ మరొకది — శాంతి, ఉపసంహరణ యొక్క వైపు: చుట్టూ అన్నీ శాంతియుతంగా ఉన్నాయి, శబ్దం మరియు ప్రదర్శన చాలా తక్కువ, కేవలం ప్రకృతి తన జంతువులు, పువ్వులు మరియు పర్వతాలతో. వీటిలో ఏదీ సంపూర్ణ చిత్రంగా లేదు. ఒక వ్యక్తి ఒంటరితనానికి అలవాటు పడితే, ప్రపంచంలోని ఉల్లాసభరిత గర్భంలోకి తీసుకువచ్చినప్పుడు, అతను దానితో నాశనం అవుతాడు; సముద్రంలో జీవించే చేపను పోలి ఉంది, అది ఉపరితలానికి తీసుకువచ్చిన వెంటనే, దానిని కట్టబెట్టిన నీటి బరువు లేకుండా ముక్కలవుతుంది. జీవితంలోని కలహం మరియు ఉల్లాసానికి అలవాటు అయిన వ్యక్తి, నిశ్శబ్దమైన ప్రదేశానికి వచ్చినప్పుడు సుఖంగా జీవించగలడా? అతను బాధపడతాడు మరియు కచ్చితంగా తన మతిని కోల్పోవచ్చు. ఆదర్శ వ్యక్తి, అత్యంత నిశ్శబ్దం మరియు ఒంటరితనంలో, అత్యంత చురుకైన కార్యకలాపాన్ని కనుగొంటాడు, మరియు అత్యంత చురుకైన కార్యకలాపంలో, అరణ్యంలోని నిశ్శబ్దం మరియు ఒంటరితనాన్ని కనుగొంటాడు. అతను ఆత్మ నియంత్రణ యొక్క రహస్యం నేర్చుకున్నాడు, అతను తనను తాను నియంత్రించుకున్నాడు. అతను పెద్ద నగరంలోని వీధులలో, అన్ని రకాల రవాణాతో కలిసి నడుస్తున్నాడు, మరియు అతని మనసు ఒక గుహలో ఉన్నట్లుగా శాంతంగా ఉంది, అక్కడ ఏ శబ్దం కూడా అతనికి చేరదు; మరియు అతను ప్రతి క్షణం తీవ్రంగా పనిచేస్తున్నాడు. ఇది కర్మ-యోగ యొక్క ఆదర్శం, మరియు మీరు దీన్ని సాధించగలిగితే, మీరు నిజంగా పని యొక్క రహస్యం నేర్చుకున్నారు.\n\nకానీ మేము ప్రారంభం నుండి ప్రారంభించాలి, మాకు వచ్చే పనులను స్వీకరించాలి మరియు ప్రతి రోజు క్రమంగా మరింత నిర selfish గా మారాలి. మేము పనిని చేయాలి మరియు మాకు ప్రేరణ కలిగించే శక్తిని కనుగొనాలి; మరియు, దాదాపు ప్రతి సందర్భంలో, మొదటి సంవత్సరాలలో, మా ప్రేరణలు ఎల్లప్పుడూ స్వార్థంగా ఉంటాయని మేము కనుగొంటాము; కానీ క్రమంగా ఈ స్వార్థత పట్టుదల ద్వారా కరిగిపోతుంది, చివరికి నిజంగా నిర selfish గా పని చేయగలిగే సమయం వస్తుంది. మనం అందరం ఆశించవచ్చు, ఒక రోజు లేదా మరొక రోజు, జీవన మార్గాలలో పోరాడుతూ, మనం పూర్తిగా స్వార్థరహితులుగా మారే సమయం వస్తుందని; ఆ స్థితిని చేరుకున్న క్షణంలో, మన所有 శక్తులు కేంద్రీకృతమవుతాయి, మరియు మనకు ఉన్న జ్ఞానం ప్రकटమవుతుంది.'
    ),
    Article(
        heading: 'స్వామి వివేకానంద భారతదేశంపై',
        body: 'స్వామి వివేకానందుని ఉల్లేఖనాలు, వ్యాఖ్యలు మరియు మాటలు—\n\nభారతీయ జీవితం యొక్క అన్ని చరిత్ర వేదాంతం యొక్క ఆలోచనను సాకారం చేసుకోవడానికి మంచి లేదా చెడు అదృష్టం ద్వారా జరిగే పోరాటం. \n\nపశ్చిమ ఆలోచనల యొక్క సంస్థాపన మరియు బాహ్య నాగరికత మన దేశంలో ప్రవేశిస్తున్నప్పుడు, మనకు అవి కావాలా లేదా అనే విషయానికి సంబంధం లేకుండా, భారతీయ ఆధ్యాత్మికత మరియు తత్వశాస్త్రం పశ్చిమ దేశాలను వరదలాగా కప్పేస్తున్నాయి. దీనిని ఎవరూ అడ్డుకోవడం సాధ్యం కాదు, అలాగే పశ్చిమ నుండి వచ్చే కొంత భౌతిక నాగరికతను కూడా మనం అడ్డుకోవడం సాధ్యం కాదు. కొంతమేర, అది మనకు మంచిది, మరియు కొంత ఆధ్యాత్మికత పశ్చిమకు మంచిది; అలా సమతుల్యత నిలుపబడుతుంది. మనం పాశ్చాత్యుల నుండి అన్నీ నేర్చుకోవాలి అనేది కాదు, లేదా వారు మన నుండి అన్నీ నేర్చుకోవాలి అనేది కాదు, కానీ ప్రతి ఒక్కరూ తమకు ఉన్నదాన్ని భవిష్యత్తులో ఆ కలను సాధించడానికి అవసరమైనది - జాతుల సమన్వయం, ఒక ఆదర్శ ప్రపంచం - భవిష్యత్తు తరాలకు అందించాలి. ఆ ఆదర్శ ప్రపంచం ఎప్పుడైనా వస్తుందా లేదా నాకు తెలియదు, ఆ సామాజిక సంపూర్ణత ఎప్పుడైనా చేరుకుంటుందా అనే విషయంలో నాకు సందేహాలు ఉన్నాయి; అది వస్తుందా లేదా, మనలో ప్రతి ఒక్కరూ ఆ ఆలోచన కోసం పని చేయాలి, అది రేపు వస్తుందని, మరియు అది కేవలం తన పని మీద ఆధారపడి ఉందని భావిస్తూ. మనలో ప్రతి ఒక్కరూ ప్రపంచంలో ఉన్న ప్రతి ఒక్కరూ తమ పని చేసారని నమ్మాలి, మరియు ప్రపంచాన్ని సంపూర్ణంగా చేయడానికి మిగిలిన పని కేవలం తనదే అని తెలుసుకోవాలి. ఇది మనపై ఉన్న బాధ్యత. \n\nనమ్మండి, నమ్మండి, ఆజ్ఞ వెలువడింది, ప్రభువుని ఆజ్ఞ వెలువడింది — భారతదేశం ఉత్కృష్టించాలి, ప్రజలు మరియు పేదలు సంతోషంగా ఉండాలి. \n\nరా, పురుషులుగా మారండి! మీ కఠినమైన గుహల నుంచి బయట రా మరియు చుట్టూ చూడండి. దేశాలు ఎలా ముందుకు సాగుతున్నాయో చూడండి! మీ దేశాన్ని ప్రేమిస్తారా? అయితే రా, మనం ఉన్నతమైన మరియు మెరుగైన విషయాల కోసం పోరాడుదాం; వెనక్కి చూడకండి, కాదు, మీరు అత్యంత ప్రియమైన మరియు సమీపమైనవారిని కేకలు వేస్తున్నా కూడా. వెనక్కి చూడకండి, కానీ ముందుకు చూడండి! \n\nప్రతి దేశానికి జీవితం లో ప్రధాన ప్రవాహం ఉంది, భారతదేశంలో అది ధర్మం. దృఢంగా ఉంచండి, రెండు వైపులా ఉన్న నీళ్లు కూడా దాని వెంట కదలాలి. \n\nఇది ఇవ్వడం మరియు తీసుకోవడం అనే నిబంధన; మరియు భారతదేశం మళ్లీ తనను తాను ఎదగాలనుకుంటే, ఆమె తన అద్భుతాలను వెలికి తీసి, భూమిపై ఉన్న జాతుల మధ్య విస్తరించాలి, మరియు ప్రత్యామ్నాయంగా ఇతరులు ఆమెకు ఇవ్వాలనుకునే విషయాలను స్వీకరించడానికి సిద్ధంగా ఉండాలి. విస్తరణ జీవితం, కుదింపు మరణం. ప్రేమ జీవితం, ద్వేషం మరణం. మేము ఇతర జాతులపై ద్వేషం పెట్టడం ప్రారంభించిన రోజు మేము మరణించడం ప్రారంభించాము; మరియు మేము జీవితం అయిన విస్తరణకు తిరిగి రాకుండా, మా మరణాన్ని ఏం ఆపలదు.\n\nఇర్ష్య మరియు అహంకారాన్ని వదలండి. ఇతరుల కోసం కలిసి పనిచేయడం నేర్చుకోండి. ఇది మా దేశానికి అత్యంత అవసరం. \n\nఇక్కడ భారతదేశంలో, మతం జాతీయ హృదయానికి కేంద్రాన్ని ఏర్పరుస్తుంది. ఇది జాతీయ నిర్మాణం నిర్మించబడిన పునాది, పునాదికలు, వెన్నెముక. \n\nఇది ఆశీర్వదించిన భూమి, పునాది, వెన్నెముక, జీవన కేంద్రం ధర్మం మరియు ధర్మం మాత్రమే. \n\nభారతదేశంలో ప్రజలను నిర్లక్ష్యం చేయడం మహా జాతీయ పాపమని నేను భావిస్తున్నాను, ఇది మన పతనానికి ఒక కారణం. ప్రజలు మళ్ళీ బాగా చదువుకున్న, బాగా ఆహారం పొందిన, బాగా చూసుకునే వరకు రాజకీయాలకు ఎలాంటి ప్రయోజనం ఉండదు. వారు మన విద్యకు చెల్లిస్తారు, వారు మన దేవాలయాలను నిర్మిస్తారు, కానీ ప్రతిఫలంగా వారికి కిక్కులు మాత్రమే వస్తాయి. వారు వాస్తవానికి మన దాసులే. భారతదేశాన్ని పునరుత్తేజం చేయాలంటే, మనం వారి కోసం పనిచేయాలి. నేను మొదటగా రెండు కేంద్ర సంస్థలను ప్రారంభించాలనుకుంటున్నాను - ఒకటి మద్రాసులో మరియు మరొకటి కలకత్తాలో - యువకులను ఉపదేశకులుగా శిక్షణ ఇవ్వడానికి. కలకత్తా కేంద్రాన్ని ప్రారంభించడానికి నిధులు ఉన్నాయి. ఇంగ్లీష్ ప్రజలు నా ఉద్దేశానికి నిధులు కనుగొంటారు. \n\nభారతదేశం ఎప్పుడూ నిష్క్రియంగా ఉందనే ఆలోచనను నేను విసర్జిస్తున్నాను. \n\nప్రపంచంలో మతాన్ని అర్థం చేసుకునే ఒక్క దేశం మాత్రమే ఉంది — అది భారతదేశం. \n\nభారతదేశంలో ఆధ్యాత్మికత చాలా ఉంది, అంతగా ఆధ్యాత్మిక మహత్వం భారతదేశాన్ని ఆ సమయంలో ఉన్న జాతులలో అత్యంత గొప్ప దేశంగా చేసింది; మరియు సంప్రదాయాలు, ఆశలు నమ్మితే, ఆ రోజులు మళ్లీ మనకు వస్తాయి, మరియు అది మీపై ఆధారపడి ఉంది. \n\nభారతదేశంలో తల్లి కుటుంబానికి కేంద్రం మరియు మన అత్యున్నత ఆదర్శం. ఆమె మనకు దేవుని ప్రతినిధి, ఎందుకంటే దేవుడు విశ్వానికి తల్లి. \n\nతత్త్వశాస్త్రంలో, మేము ఇప్పటికీ ఇతర దేశాల కంటే అధికంగా ఉన్నాము, అని గొప్ప జర్మన్ తత్త్వవేత్త షోపెన్‌హాయర్ అంగీకరించాడు. \n\nభారతదేశం చనిపోయే వరకు యూరోప్ కావడం లేదు. \n\nనేను వెళ్లకముందు భారతదేశాన్ని ప్రేమించాను. ఇప్పుడు భారతదేశం యొక్క ధూళి కూడా నాకు పవిత్రంగా మారింది, ఇప్పుడు ఆకాశం కూడా నాకు పవిత్రంగా ఉంది; ఇది ఇప్పుడు పవిత్ర భూమి, యాత్ర స్థలం, తీర్థం.\n\nభారతదేశం భారతదేశమే.\n\nభారతదేశం నిజమైన శక్తిని, అంటే వినయం, ప్రదర్శిస్తుంది.\n\nమ్లేచ్ఛ అనే పదాన్ని ఆవిష్కరించిన రోజు భారతదేశం యొక్క విధి ముద్రితమైంది మరియు ఇతరులతో సంబంధం కట్ చేసుకుంది.\n\nభారతదేశం యొక్క హృదయం విరిగిపోవాలి, మరియు ఆధ్యాత్మికత యొక్క ప్రవాహం బయటకు వస్తుంది.\n\nభారతదేశం యొక్క సామర్థ్యాలు గొప్పవి మరియు అవి ఆహ్వానించబడతాయి.\n\nభారతదేశం యొక్క ప్రధాన అంశం ధర్మం. సామాజిక సవరణ మరియు ఇతర విషయాలు ద్వితీయమైనవి.\n\nభారతదేశంలో పేదరికం, పూజారి శక్తి మరియు అణచివేత ద్వారా బంధించబడిన కోట్ల మందికి ప్రతి ఒక్కరూ రాత్రి మరియు రోజూ ప్రార్థించాలి— వారికోసం రాత్రి మరియు రోజూ ప్రార్థించండి. నేను వారికోసం ధర్మాన్ని preach చేయడానికి ఎక్కువ శ్రద్ధ చూపిస్తాను, ఉన్నతుల మరియు ధనవంతుల కంటే. నేను మెటాఫిజిషియన్ కాదు, తత్త్వవేత్త కాదు, సంత్ కూడా కాదు. కానీ నేను పేదవాడిని, పేదలను ప్రేమిస్తున్నాను.\n\nభారతదేశంలో జాతీయ ఐక్యత అనేది దాని చల్లని ఆధ్యాత్మిక శక్తులను సమీకరించడం కావాలి. భారతదేశంలో ఒక జాతి అనేది ఒకే ఆధ్యాత్మిక రాగానికి తాళములు కొట్టే వారి ఐక్యత కావాలి.\n\nఈ ఆశీర్వాదిత దేశంలో చలనశీలత మరెక్కడా ఈ స్థాయిలో కనిపించలేదు, మరియు ఈ చలనశీలతకు గొప్ప సాక్ష్యం ఏమిటంటే, మన ప్రాచీన మరియు మహానుభావమైన జాతి ఇంకా జీవిస్తున్నది, మరియు ప్రతి దశాబ్దంలో ఈ గొప్ప ప్రయాణంలో కొత్త యువతను పొందుతున్నట్లు కనిపిస్తుంది — మరణించని మరియు నాశనముకాకుండా.\n\nనేను మీకు ఒక విషయం చెప్పాలి. భారతదేశంలో విగ్రహ పూజ అనేది ఏదైనా భయంకరమైనది కాదు. ఇది వేశ్యల తల్లి కాదు. దాని బదులుగా, ఇది అభివృద్ధి చెందని మనసుల అధిక ఆధ్యాత్మిక సత్యాలను grasp చేయడానికి చేసిన ప్రయత్నం. హిందువులకు కొన్ని లోపాలు ఉన్నాయ్, వారు కొన్నిసార్లు కొన్ని మినహాయింపులు కలిగి ఉంటారు; కానీ ఇది గమనించండి, వారు ఎప్పుడూ తమ శరీరాలను శిక్షించడానికి సిద్ధంగా ఉంటారు, మరియు తమ పొరుగువారిని కత్తిరించడానికి కాదు. హిందూ ఉగ్రవాది తనను తాను అగ్నిలో వేస్తే, అతను విచారణ యొక్క అగ్ని వెలిగించడు. మరియు ఈ విషయం కూడా అతని ధర్మానికి సంబంధించినది కాదు, అలాగే మంత్రాలపై నిందలు వేయడం క్రైస్తవతానికి సంబంధించినది కాదు.\n\nరాజకీయ మహత్త్వం లేదా సైనిక శక్తి మన జాతి యొక్క మిషన్ కాదు; ఇది ఎప్పుడూ లేదు, మరియు, నా మాటలు గమనించండి, ఇది ఎప్పుడూ ఉండదు.\n\nపూజారుల కళా భారతదేశానికి శాపం. మనిషి తన సోదరుడిని అవమానించగలడా మరియు తాను అవమానం నుండి తప్పించుకోగలడా? \n\nభారతదేశ ప్రజలకీ ధర్మం ఒక్కటే మరియు ఏకైక ఆసక్తి. \n\nభారతీయ మేధస్సు అభివృద్ధి చెందడంలో ధర్మం ప్రత్యేకత. \n\nరాష్ట్రం కట్టెలో జీవిస్తుంది అని గుర్తుంచుకోండి. కానీ, ఆహా! వారు కోసం ఎవరూ ఎప్పుడూ ఏమీ చేయలేదు. \n\nఈ మాతృభూమి, మనది, దీర్ఘ నిద్ర నుండి మేల్కొంటోంది. ఎవరూ ఆమెను ఇకపై ఆపలేరు; ఆమె ఇకపై నిద్రపోనుంది; ఎలాంటి బాహ్య శక్తులు ఆమెను ఇకపై నిలువరించలేవు; ఎందుకంటే అనంతమైన మహానేత ఆమె కాళ్లకు ఎగువకు వస్తోంది.\n\nభారతదేశం పాడయిన ప్రధాన కారణం, గర్వం మరియు రాజకీయ అధికారంతో, కొద్ది మందికి విద్య మరియు జ్ఞానాన్ని మోపడం.\n\nప్రపంచం మొత్తం ఇప్పుడు ఆధ్యాత్మిక ఆహారానికి ఈ భారతదేశం వైపు చూస్తోంది; భారతదేశం అన్ని జాతులకు దాన్ని అందించాలి. ఇక్కడ మాత్రమే మానవత్వానికి ఉత్తమ ఆలోచన ఉంది; మరియు పాశ్చాత్య పండితులు ఇప్పుడు ఈ ఆలోచనను అర్థం చేసుకోవడానికి ప్రయత్నిస్తున్నారు, ఇది మన సంస్కృత సాహిత్యం మరియు తత్త్వశాస్త్రంలో ఉంచబడింది, మరియు ఇది భారతదేశానికి శాశ్వతంగా ప్రత్యేకతను ఇచ్చింది.\n\nమన జాతి చరిత్ర చూపిస్తుంది कि భారతదేశం ఎప్పుడూ అత్యంత చురుకుగా ఉంది.\n\nభారతీయ మేధస్సు మొదట ధార్మికంగా ఉంటుంది, తరువాత ఏదైనా.\n\nభారతదేశంలో అన్ని చెడు మూలం ఒకే విషయం పేదల పరిస్థితి.\n\nభారతదేశానికి ఏకైక ఆశ ప్రజలలోనే ఉంది. ఉన్నత తరగతులు శారీరకంగా మరియు నైతికంగా మృతులుగా ఉన్నాయి. . . .\n\nభారతదేశంలో పేదలు, దిగువవర్గాలు, పాపి లకు ఎవరూ స్నేహితులు, సహాయం లేదు — వారు ఎటువంటి ప్రయత్నం చేసినా ఎరుగని స్థాయికి చేరుకోలేరు. ప్రతి రోజు వారు దిగజారుతూ, కఠోర సమాజం వారి మీద పడుతున్న దెబ్బలను అనుభవిస్తున్నారు, కానీ దెబ్బ ఎక్కడి నుండి వస్తుందో వారికి తెలియదు. వారు కూడా మనుషులని మర్చిపోయారు.\n\nమన భాగంలో శతాబ్దాల నిర్లక్ష్యం మరియు మన విజేతల భాగంలో అవమానం ప్రాచీన ఆర్యావర్త యొక్క మహిమలను స్పష్టంగా మసకబార్చాయి, అనేక గొప్ప స్తంభాలు, అనేక అందమైన అర్చలు మరియు అనేక అద్భుతమైన మూలలు శతాబ్దాల పాటు వరదలతో కరిగిపోయాయి — కానీ కేంద్రం అటువంటి దెబ్బలకు దూరంగా ఉంది, కీలక రాయి అప్రభావితంగా ఉంది. దైవానికి మరియు అన్ని జీవులకు దానానికి అంకితమైన అద్భుతమైన మహిమ యొక్క స్మారకాన్ని నిర్మించిన ఆ ఆధ్యాత్మిక ప్రాతిపదిక అచలంగా, ఎప్పుడూ బలంగా నిలబడింది. \n\nనా అభిప్రాయానికి, భారతదేశం పతనమై, క్షీణించిన ప్రధాన కారణం అన్యుల పట్ల ద్వేషం ఆధారంగా దేశం చుట్టూ నిర్మించిన ఆచారాల గోడ. పురాతన కాలంలో దీనికి ఉన్న నిజమైన లక్ష్యం హిందువులను చుట్టుపక్కల ఉన్న బౌద్ధ దేశాలతో సంబంధం కలిగి ఉండకుండా అడ్డుకోవడం. \n\nమనం బాల్య కాలం నుండి ప్రతికూల విద్యను పొందాము. మనం ఎవరో కాదు అని మాత్రమే నేర్చుకున్నాము. మన దేశంలో గొప్ప వ్యక్తులు జన్మించినట్లు మనకు అర్థం చేసుకోవడానికి అరుదుగా అవకాశం లభించింది. మనకు పాజిటివ్‌గా ఏమీ నేర్పబడలేదు. మనం చేతులు, కాళ్లు ఎలా ఉపయోగించాలో కూడా తెలియదు! ఇంగ్లీష్ పూర్వీకుల గురించి అన్ని విషయాలు, సంఖ్యలు నేర్చుకున్నాము, కానీ మన పూర్వీకుల గురించి విచారంగా తెలియదు. మనం కేవలం బలహీనతను మాత్రమే నేర్చుకున్నాము. ఓ జయించిన జాతిగా, మనం బలహీనులమని, ఏదీ స్వతంత్రంగా చేయలేమని నమ్మించుకున్నాము. కాబట్టి, శ్రద్ధ ఎలా కోల్పోతుంది? నిజమైన శ్రద్ధ భావనను మళ్ళీ మనకు తీసుకురావాలి, మనలోని ఆత్మ విశ్వాసాన్ని పునరుజ్జీవితం చేయాలి, అప్పుడు మాత్రమే, మన దేశాన్ని ఎదుర్కొనే అన్ని సమస్యలు మనమే క్రమంగా పరిష్కరించగలుగుతాము. మనకు తెలుసు, భారతీయ మనస్సుకు మత సిద్ధాంతాల కంటే ఉన్నతమైనది ఏమీ లేదు, ఇది భారతీయ జీవితానికి ప్రధాన స్వరంగా ఉంది. \n\nభారతదేశం కోరుకుంటున్నది జాతీయ రక్తంలో కొత్త శక్తిని ఉత్ప్రేరకం చేసే కొత్త విద్యుత్ అగ్ని. \n\nభారతదేశం యొక్క నిజమైన చరిత్ర బయటపడినప్పుడు, మత విషయాలలో ఎలా ఉన్నారో, అందులోనే కళలలో కూడా, భారతదేశం మొత్తం ప్రపంచానికి ప్రాథమిక గురువుగా ఉన్నది అని నిరూపించబడుతుంది.'
    ),
  ],
);
